import re,glob,collections
# top-level function declarations in apis whose parameter list contains an arrow-typed parameter; group by name and flag names whose overloads differ only in arrow-typed params
for f in sorted(glob.glob('Library/*.fsi')):
    decls=collections.defaultdict(list)
    for i,l in enumerate(open(f,encoding='utf-8',errors='replace')):
        m=re.match(r'^(opr\s+\S+|[a-z_][A-Za-z0-9_]*)\s*(\[\\.*?\\\])?\s*\((.*)\)\s*:',l)
        if m: decls[m.group(1)].append((i+1,m.group(3)))
    for n,ds in decls.items():
        if len(ds)<2: continue
        arrows=[d for d in ds if '->' in d[1]]
        if len(arrows)>=2:
            # strip arrow types and compare the rest
            def skel(p): return re.sub(r'\([^()]*\)\s*->\s*\S+|\S+\s*->\s*\S+','ARROW',p)
            sk=collections.Counter(re.sub(r'\w+\s*:','',skel(d[1])).replace(' ','') for d in arrows)
            dup=[k for k,v in sk.items() if v>1]
            if dup: print(f,n,[d[0] for d in arrows],dup[:2])
EOF

